#include <iostream>
#include <string_view>

int main()
{
    // Safe: points to static array (string literals persist)
    std::string_view good{"a string literal"};

    // BAD: dangling pointer! std::string temporary destroyed at end of statement
    // std::string_view bad{"a temporary string"s}; // DON'T DO THIS

    // Lightweight operations - no allocation
    constexpr std::string_view sv{"Hello, World!"};
    std::cout << sv.substr(0, 5) << '\n';  // "Hello"
    std::cout << sv.find(',') << '\n';      // 5

    return 0;
}

// Type aliases provided by <string_view>
// std::string_view   -> std::basic_string_view<char>
// std::wstring_view  -> std::basic_string_view<wchar_t>
// std::u16string_view -> std::basic_string_view<char16_t>
// std::u32string_view -> std::basic_string_view<char32_t>

// Key member functions:
// - size(), length()    : character count (O(1))
// - data()               : pointer to underlying array
// - operator[]           : element access (no bounds check)
// - at()                 : element access (with bounds check)
// - substr()             : create view of substring
// - remove_prefix(n)     : advance start by n chars
// - remove_suffix(n)     : reduce size by n chars
// - starts_with() (C++20): check prefix
// - ends_with() (C++20)  : check suffix
// - contains() (C++23)   : check for substring
